-- 1. Runtime roles
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_floor_runtime') THEN
    CREATE ROLE "factory_floor_runtime" NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_floor_runtime' AND (rolcanlogin OR rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN
    RAISE EXCEPTION 'Runtime role factory_floor_runtime must be NOLOGIN and hold no administrative attribute';
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_partner_runtime') THEN
    CREATE ROLE "factory_partner_runtime" NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_partner_runtime' AND (rolcanlogin OR rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN
    RAISE EXCEPTION 'Runtime role factory_partner_runtime must be NOLOGIN and hold no administrative attribute';
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_platform') THEN
    CREATE ROLE "factory_platform" NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_platform' AND (rolcanlogin OR rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN
    RAISE EXCEPTION 'Runtime role factory_platform must be NOLOGIN and hold no administrative attribute';
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_runtime') THEN
    CREATE ROLE "factory_runtime" NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_runtime' AND (rolcanlogin OR rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN
    RAISE EXCEPTION 'Runtime role factory_runtime must be NOLOGIN and hold no administrative attribute';
  END IF;
END $$;

-- 2. The runtime login
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_app') THEN
    CREATE ROLE "factory_app" LOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'factory_app' AND (rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN
    RAISE EXCEPTION 'Runtime login factory_app must hold no administrative attribute';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'factory_floor_runtime'::regrole AND m.member = 'factory_app'::regrole AND m.set_option AND NOT m.inherit_option) THEN
    GRANT "factory_floor_runtime" TO "factory_app" WITH INHERIT FALSE, SET TRUE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'factory_partner_runtime'::regrole AND m.member = 'factory_app'::regrole AND m.set_option AND NOT m.inherit_option) THEN
    GRANT "factory_partner_runtime" TO "factory_app" WITH INHERIT FALSE, SET TRUE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'factory_platform'::regrole AND m.member = 'factory_app'::regrole AND m.set_option AND NOT m.inherit_option) THEN
    GRANT "factory_platform" TO "factory_app" WITH INHERIT FALSE, SET TRUE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'factory_runtime'::regrole AND m.member = 'factory_app'::regrole AND m.set_option AND NOT m.inherit_option) THEN
    GRANT "factory_runtime" TO "factory_app" WITH INHERIT FALSE, SET TRUE;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.member = 'factory_app'::regrole AND (m.inherit_option OR m.admin_option)) THEN
    RAISE EXCEPTION 'Runtime login factory_app must not inherit or administer a role: grant its roles WITH INHERIT FALSE, SET TRUE';
  END IF;
END $$;

