CREATE POLICY "factory_runtime_update" ON "public"."Station" AS PERMISSIVE FOR UPDATE TO "factory_runtime" USING ("tenantId" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid) WITH CHECK ("tenantId" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid);
-- "public"."Tenant"
ALTER TABLE "public"."Tenant" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."Tenant" FORCE ROW LEVEL SECURITY;
DO $$ DECLARE existing record; BEGIN FOR existing IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'Tenant' LOOP EXECUTE format('DROP POLICY %I ON %I.%I', existing.policyname, 'public', 'Tenant'); END LOOP; END $$;
REVOKE ALL ON TABLE "public"."Tenant" FROM PUBLIC, "factory_floor_runtime", "factory_partner_runtime", "factory_platform", "factory_runtime";
GRANT SELECT ON TABLE "public"."Tenant" TO "factory_floor_runtime";
GRANT SELECT ON TABLE "public"."Tenant" TO "factory_runtime";
CREATE POLICY "factory_floor_runtime_select" ON "public"."Tenant" AS PERMISSIVE FOR SELECT TO "factory_floor_runtime" USING ("id" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid);
CREATE POLICY "factory_runtime_select" ON "public"."Tenant" AS PERMISSIVE FOR SELECT TO "factory_runtime" USING ("id" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid);
